//! Private, versioned S3 storage. Provider keys are generated by the transfer journal.
//! Credentials and signed URLs never enter persisted request digests or diagnostic errors.
use super::{storage::key_valid, *};
mod downloads;
mod uploads;
pub(super) use uploads::ConfirmUpload;
mod marker;
mod transport;
use axum::http::{Method, Request, Response};
use marker::RootMarker;
use opendal::{Buffer, HttpBody, HttpTransport, HttpTransporter, OperationContext, Operator};
use reqsign_aws_v4::{Credential, RequestSigner, StaticCredentialProvider};
use reqsign_core::{Context, Signer};
use serde::{Deserialize, Serialize};
use sqlx::{Connection, PgConnection};
use std::{ops::Range, path::PathBuf};
use tokio_stream::StreamExt;
use transport::Transport;

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Registration {
    endpoint: String,
    region: String,
    bucket: String,
    prefix: String,
    credentials_file: PathBuf,
}
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Credentials {
    access_key: String,
    secret_key: String,
    session_token: Option<String>,
}

fn safe_version(value: &str) -> bool {
    value != "null"
        && !value.is_empty()
        && value.len() <= 1024
        && value.bytes().all(|c| c.is_ascii_graphic())
}
fn component(value: &str) -> bool {
    !value.is_empty()
        && value.len() <= 63
        && value
            .bytes()
            .all(|c| c.is_ascii_alphanumeric() || matches!(c, b'-' | b'_'))
}
pub(super) struct VersionedStore {
    pub root_id: String,
    pool: PgPool,
    op: Operator,
    bucket_url: reqwest::Url,
    prefix: String,
    signer: Signer<Credential>,
    writer_lock: Option<Mutex<PgConnection>>,
    marker: RootMarker,
}

#[derive(Serialize)]
pub(super) struct DownloadAuthorization {
    pub artifact_id: String,
    pub version_id: String,
    pub sha256: String,
    pub size_bytes: String,
    pub url: String,
    pub expires_at_unix: String,
}

impl VersionedStore {
    pub async fn open(pool: PgPool, path: &Path, writable: bool) -> Result<Self, ArtifactError> {
        fn load<T: serde::de::DeserializeOwned>(p: &Path) -> Result<T, ArtifactError> {
            let bytes =
                crate::connector_file::read_private(p).map_err(|_| ArtifactError::StoragePolicy)?;
            serde_json::from_slice(&bytes).map_err(|_| ArtifactError::StoragePolicy)
        }
        let cfg: Registration = load(path)?;
        let mut endpoint =
            reqwest::Url::parse(&cfg.endpoint).map_err(|_| ArtifactError::StoragePolicy)?;
        let local = endpoint.host_str().is_some_and(|s| {
            s.trim_matches(['[', ']'])
                .parse::<std::net::IpAddr>()
                .is_ok_and(|ip| ip.is_loopback())
        });
        if !(endpoint.scheme() == "https" || endpoint.scheme() == "http" && local)
            || endpoint.host_str().is_none()
            || !endpoint.username().is_empty()
            || endpoint.password().is_some()
            || endpoint.query().is_some()
            || endpoint.fragment().is_some()
            || endpoint.path() != "/"
            || !component(&cfg.region)
            || !(3..=63).contains(&cfg.bucket.len())
            || !cfg.bucket.split('.').all(|v| {
                !v.is_empty()
                    && !v.starts_with('-')
                    && !v.ends_with('-')
                    && v.bytes()
                        .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == b'-')
            })
            || cfg.prefix.len() > 256
            || !cfg.prefix.split('/').all(component)
            || !cfg.credentials_file.is_absolute()
        {
            return Err(ArtifactError::StoragePolicy);
        }
        let creds: Credentials = load(&cfg.credentials_file)?;
        if creds.access_key.is_empty()
            || creds.secret_key.is_empty()
            || creds.session_token.as_deref() == Some("")
        {
            return Err(ArtifactError::StoragePolicy);
        }
        let transport = Transport {
            client: reqwest::Client::builder()
                .no_proxy()
                .redirect(reqwest::redirect::Policy::none())
                .connect_timeout(Duration::from_secs(3))
                .timeout(Duration::from_secs(25))
                .build()
                .map_err(|_| ArtifactError::Unavailable)?,
            origin: endpoint.origin().ascii_serialization(),
        };
        let mut builder = opendal::services::S3::default()
            .endpoint(transport.origin.as_str())
            .region(&cfg.region)
            .bucket(&cfg.bucket)
            .root(&cfg.prefix)
            .access_key_id(&creds.access_key)
            .secret_access_key(&creds.secret_key)
            .checksum_algorithm("crc32c")
            .disable_config_load()
            .disable_ec2_metadata();
        let mut credentials = StaticCredentialProvider::new(&creds.access_key, &creds.secret_key);
        if let Some(token) = &creds.session_token {
            builder = builder.session_token(token);
            credentials = credentials.with_session_token(token);
        }
        let op = Operator::new(builder)?.with_context(
            OperationContext::new().with_http_transport(HttpTransporter::new(transport.clone())),
        );
        let signer = Signer::new(
            Context::new(),
            credentials,
            RequestSigner::new("s3", &cfg.region),
        );
        let root_id = format!(
            "s3-{}",
            request_digest(
                "artifact.s3.root.v1",
                &(&transport.origin, &cfg.region, &cfg.bucket, &cfg.prefix)
            )
            .map_err(|_| ArtifactError::Invalid)?
        );
        endpoint.set_path(&format!("/{}/", cfg.bucket));
        Self::check_versioning(&endpoint, &signer, &transport).await?;
        let writer_lock = if writable {
            let mut con = PgConnection::connect_with(&pool.connect_options()).await?;
            let acquired: bool =
                sqlx::query_scalar("SELECT pg_try_advisory_lock(hashtextextended($1, 88))")
                    .bind(&root_id)
                    .fetch_one(&mut con)
                    .await?;
            if !acquired {
                return Err(ArtifactError::Busy);
            }
            Some(Mutex::new(con))
        } else {
            None
        };
        let marker = RootMarker::bind(&pool, &op, &root_id, writable).await?;
        Ok(Self {
            root_id,
            pool,
            op,
            bucket_url: endpoint,
            prefix: cfg.prefix,
            signer,
            writer_lock,
            marker,
        })
    }
    async fn check_versioning(
        endpoint: &reqwest::Url,
        signer: &Signer<Credential>,
        transport: &Transport,
    ) -> Result<(), ArtifactError> {
        #[derive(Deserialize)]
        struct Versioning {
            #[serde(rename = "Status")]
            status: String,
        }
        let mut url = endpoint.clone();
        url.set_path(url.path().trim_end_matches('/').to_owned().as_str());
        url.set_query(Some("versioning"));
        let req = Request::builder()
            .method(Method::GET)
            .uri(url.as_str())
            .body(())
            .map_err(|_| ArtifactError::StoragePolicy)?;
        let (mut parts, _) = req.into_parts();
        signer
            .sign(&mut parts, None)
            .await
            .map_err(|_| ArtifactError::StoragePolicy)?;
        let mut response = transport
            .client
            .get(parts.uri.to_string())
            .headers(parts.headers)
            .send()
            .await
            .map_err(|_| ArtifactError::Unavailable)?;
        if !response.status().is_success() {
            return Err(ArtifactError::StoragePolicy);
        }
        let mut bytes = Vec::new();
        while let Some(part) = response
            .chunk()
            .await
            .map_err(|_| ArtifactError::Unavailable)?
        {
            if part.len() > 4096 - bytes.len() {
                return Err(ArtifactError::StoragePolicy);
            }
            bytes.extend_from_slice(&part);
        }
        let version: Versioning = quick_xml::de::from_reader(bytes.as_slice())
            .map_err(|_| ArtifactError::StoragePolicy)?;
        if version.status != "Enabled" {
            return Err(ArtifactError::StoragePolicy);
        }
        Ok(())
    }
    async fn writer_authority(&self) -> Result<(), ArtifactError> {
        let mut lock = self
            .writer_lock
            .as_ref()
            .ok_or(ArtifactError::StoragePolicy)?
            .lock()
            .await;
        // A dedicated connection cannot transparently reconnect and silently lose its lock.
        sqlx::query("SELECT 1").execute(&mut *lock).await?;
        self.marker.verify(&self.op).await
    }
    pub async fn writer(&self, key: &str) -> Result<opendal::Writer, ArtifactError> {
        key_valid(key)?;
        self.writer_authority().await?;
        Ok(self
            .op
            .writer_with(key)
            .content_type("application/octet-stream")
            .content_disposition("attachment")
            .cache_control("private, no-store")
            .if_not_exists(true)
            .user_metadata([
                ("orange-root".to_owned(), self.root_id.clone()),
                ("orange-key".to_owned(), key.to_owned()),
            ])
            .await?)
    }
    pub async fn pin(&self, key: &str, receipt: &opendal::Metadata) -> Result<(), ArtifactError> {
        key_valid(key)?;
        self.writer_authority().await?;
        let version = receipt
            .version()
            .filter(|v| safe_version(v))
            .ok_or(ArtifactError::StoragePolicy)?;
        sqlx::query("INSERT INTO artifact_s3_versions(root_id,storage_key,provider_version) VALUES($1,$2,$3) ON CONFLICT DO NOTHING")
            .bind(&self.root_id).bind(key).bind(version).execute(&self.pool).await?;
        if self.version(key).await? != version {
            return Err(ArtifactError::Integrity);
        }
        Ok(())
    }
    async fn version(&self, key: &str) -> Result<String, ArtifactError> {
        key_valid(key)?;
        self.marker.verify(&self.op).await?;
        sqlx::query_scalar(
            "SELECT provider_version FROM artifact_s3_versions WHERE root_id=$1 AND storage_key=$2",
        )
        .bind(&self.root_id)
        .bind(key)
        .fetch_optional(&self.pool)
        .await?
        .ok_or(ArtifactError::Integrity)
    }
    pub async fn reader(&self, key: &str) -> Result<opendal::Reader, ArtifactError> {
        let v = self.version(key).await?;
        Ok(self.op.reader_with(key).version(&v).await?)
    }
    pub async fn read(
        &self,
        key: &str,
        size: u64,
        range: Range<u64>,
    ) -> Result<Buffer, ArtifactError> {
        let version = self.version(key).await?;
        let meta = self.op.stat_with(key).version(&version).await?;
        if meta.version() != Some(version.as_str())
            || meta.content_length() != size
            || range.end > size
            || range.start > range.end
        {
            return Err(ArtifactError::Integrity);
        }
        if range.is_empty() {
            return Ok(Buffer::new());
        }
        let length = range.end - range.start;
        let bytes = self
            .op
            .read_with(key)
            .version(&version)
            .range(range)
            .await?;
        if bytes.len() as u64 != length {
            return Err(ArtifactError::Integrity);
        }
        Ok(bytes)
    }
    pub async fn copy(
        &self,
        stage: &str,
        published: &str,
        size: u64,
        digest: &str,
    ) -> Result<(), ArtifactError> {
        key_valid(stage)?;
        key_valid(published)?;
        if !stage.starts_with("staging-") || !published.starts_with("published-") {
            return Err(ArtifactError::StoragePolicy);
        }
        self.writer_authority().await?;
        let version = self.version(stage).await?;
        let original = self.read(stage, size, 0..size).await?;
        if hex::encode(Sha256::digest(original.to_bytes())) != digest {
            return Err(ArtifactError::Integrity);
        }
        let receipt = self
            .op
            .copy_with(stage, published)
            .source_version(&version)
            .if_not_exists(true)
            .await?;
        self.pin(published, &receipt).await?;
        let stored = self.read(published, size, 0..size).await?;
        if hex::encode(Sha256::digest(stored.to_bytes())) != digest {
            return Err(ArtifactError::Integrity);
        }
        Ok(())
    }
    pub async fn remove(&self, key: &str) -> Result<(), ArtifactError> {
        key_valid(key)?;
        self.writer_authority().await?;
        if self.retire_direct_stage(key).await? {
            return Ok(());
        }
        let attached: Option<String> = sqlx::query_scalar(
            "SELECT provider_version FROM artifact_s3_versions WHERE root_id=$1 AND storage_key=$2",
        )
        .bind(&self.root_id)
        .bind(key)
        .fetch_optional(&self.pool)
        .await?;
        if let Some(version) = attached {
            self.op.delete_with(key).version(&version).await?;
            return match self.op.stat_with(key).version(&version).await {
                Err(e) if e.kind() == opendal::ErrorKind::NotFound => Ok(()),
                Err(e) => Err(e.into()),
                Ok(_) => Err(ArtifactError::Busy),
            };
        }
        // A crash between provider acceptance and recording the version leaves an
        // orphan. Only an exact key/version with the service's write metadata is owned.
        let mut list = self
            .op
            .lister_with(key)
            .recursive(true)
            .versions(true)
            .deleted(true)
            .await?;
        let mut versions = Vec::new();
        while let Some(entry) = list.next().await {
            let entry = entry?;
            if entry.path() == key {
                let version = entry
                    .metadata()
                    .version()
                    .filter(|v| safe_version(v))
                    .ok_or(ArtifactError::StoragePolicy)?;
                versions.push(version.to_owned());
                if versions.len() == 64 {
                    break;
                }
            }
        }
        let copied_from:Option<String>=sqlx::query_scalar("SELECT t.stage_key FROM artifact_transfers t JOIN artifacts a USING(artifact_id) WHERE a.root_id=$1 AND t.published_key=$2")
            .bind(&self.root_id).bind(key).fetch_optional(&self.pool).await?;
        for version in &versions {
            let meta = self.op.stat_with(key).version(version).await?;
            if !meta.user_metadata().is_some_and(|m| {
                m.get("orange-root") == Some(&self.root_id)
                    && m.get("orange-key")
                        .is_some_and(|v| v == key || Some(v) == copied_from.as_deref())
            }) {
                return Err(ArtifactError::StoragePolicy);
            }

            self.op.delete_with(key).version(version).await?;
        }
        // Never release capacity on unconfirmed cleanup, including a write whose response was lost.
        let mut remaining = self
            .op
            .lister_with(key)
            .recursive(true)
            .versions(true)
            .deleted(true)
            .await?;
        while let Some(entry) = remaining.next().await {
            if entry?.path() == key {
                return Err(ArtifactError::Busy);
            }
        }
        Ok(())
    }
    pub async fn checked_version(
        &self,
        key: &str,
        view: &ArtifactView,
    ) -> Result<String, ArtifactError> {
        key_valid(key)?;
        if !key.starts_with("published-") {
            return Err(ArtifactError::StoragePolicy);
        }
        let version = self.version(key).await?;
        let meta = self.op.stat_with(key).version(&version).await?;
        if meta.version() != Some(version.as_str())
            || meta.content_length().to_string() != view.size_bytes
        {
            return Err(ArtifactError::Integrity);
        }
        Ok(version)
    }
}
